export function normalizeTollRoute(data){
 const r=data.routes?.[0];if(!r)throw Error('Provedor não retornou rota.');
 const list=Array.isArray(r.tolls)?r.tolls.flat(Infinity).filter(x=>x&&typeof x==='object'):null;
 const has=r.summary?.hasTolls;
 if(has!==false&&!list)throw Error('Provedor não informou os pedágios da rota.');
 if(list?.some(t=>t.currency&&t.currency!=='BRL'))throw Error('Consulta disponível apenas para tarifas em reais.');
 const cost=has===false?0:(typeof r.costs?.cash==='number'&&Number.isFinite(r.costs.cash)&&r.costs.cash>=0?r.costs.cash:null);
 let distance=r.summary?.distance;if(typeof distance==='string'){try{distance=JSON.parse(distance)}catch{distance=null}}
 const km=Number(distance?.value)/1000;if(!Number.isFinite(km)||km<=0)throw Error('Provedor não informou a distância da rota.');
 return {cost,count:has===false?0:list?.length??null,km,url:r.summary?.url||null,tolls:(list||[]).map(t=>({name:t.name||t.start?.name||t.end?.name||'Cobrança de pedágio',cost:typeof t.cashCost==='number'?t.cashCost:null}))};
}
export async function tollAPI(request,env){
 const reply=(value,status=200)=>Response.json(value,{status,headers:{'Cache-Control':'no-store'}});
 if(request.method!=='POST')return reply({error:'Método não permitido.'},405);
 const origin=request.headers.get('Origin');if(origin&&origin!==new URL(request.url).origin)return reply({error:'Origem não permitida.'},403);
 if(!env.TOLLGURU_API_KEY)return reply({error:'Consulta automática ainda não ativada: falta configurar a chave TollGuru no servidor.'},503);
 let body;try{const raw=await request.text();if(raw.length>5000)return reply({error:'Pedido muito grande.'},413);body=JSON.parse(raw)}catch{return reply({error:'Pedido inválido.'},400)}
 const pts=body.points;if(!Array.isArray(pts)||pts.length<2||pts.length>5||pts.some(p=>!Number.isFinite(p.lat)||!Number.isFinite(p.lng)||Math.abs(p.lat)>90||Math.abs(p.lng)>180))return reply({error:'Coordenadas inválidas.'},400);
 try{
 const leg=async points=>{const r=await fetch('https://apis.tollguru.com/toll/v2/origin-destination-waypoints',{method:'POST',headers:{'Content-Type':'application/json','x-api-key':env.TOLLGURU_API_KEY},body:JSON.stringify({from:points[0],to:points.at(-1),waypoints:points.slice(1,-1),serviceProvider:'here',vehicle:{type:'2AxlesAuto'}}),signal:AbortSignal.timeout(23000)});if(!r.ok)throw Error('Provedor de pedágios indisponível ou chave/plano sem acesso.');return normalizeTollRoute(await r.json())};
 const out=await leg(pts);const back=body.roundTrip?await leg([...pts].reverse()):null;
 return reply({out,back,provider:'TollGuru',vehicle:'2AxlesAuto',payment:'cash'});
 }catch(e){return reply({error:e.message||'Falha na consulta de pedágios.'},502)}
}

const ASSETS={"/":{"data":"","type":"text/html; charset=utf-8"},"/manifest.webmanifest":{"data":"","type":"application/manifest+json"},"/sw.js":{"data":"","type":"text/javascript"},"/icons/icon-192.png":{"data":"","type":"image/png"},"/icons/icon-512.png":{"data":"","type":"image/png"}};
export default {async fetch(request,env){const path=new URL(request.url).pathname;if(path==='/api/tolls')return tollAPI(request,env);const a=ASSETS[path==='/index.html'?'/':path];if(!a)return new Response('Não encontrado',{status:404});const bytes=Uint8Array.from(atob(a.data),c=>c.charCodeAt(0));return new Response(bytes,{headers:{'Content-Type':a.type,'Cache-Control':path==='/sw.js'?'no-cache':'no-cache'}})}};